using UnityEngine;
using UnityEditor;
using UnityEditor.SceneManagement;
using System.IO;
using System.Linq;

namespace Unity.AI.Assistant.Agent.Dynamic.Extension.Editor
{
    internal class CommandScript : IRunCommand
    {
        public void Execute(ExecutionResult result)
        {
            var sc = EditorSceneManager.GetActiveScene();
            var ts = sc.GetRootGameObjects().SelectMany(g => g.GetComponentsInChildren<Transform>(true)).ToArray();
            string text = "Unity=" + Application.unityVersion + " scene=" + sc.path + " dirty=" + sc.isDirty + " play=" + EditorApplication.isPlaying + " compiling=" + EditorApplication.isCompiling + " r102exists=" + File.Exists("Assets/Scenes/JourneyPresentation_v48_r102.unity") + "\n";
            foreach (var g in sc.GetRootGameObjects())
                text += "ROOT " + g.name + " " + g.activeSelf + " " + g.transform.position + "\n";
            foreach (var t in ts.Where(t => t.name == "CR_Ha" || t.name.Contains("RegionalWalk") || t.name == "Main Camera" || t.name == "CR_Market" || t.name.Contains("Quay")))
                text += "TARGET " + t.name + " " + t.position + " components=" + string.Join(",", t.GetComponents<Component>().Where(c => c).Select(c => c.GetType().Name)) + "\n";
            Directory.CreateDirectory("Test/KetQua/investigation_r102");
            File.WriteAllText("Test/KetQua/investigation_r102/editor-preflight.txt", text);
            result.Log(text);
        }
    }
}

